import { randomUUID } from 'node:crypto'
import { escalate, type ReviewQueues } from '../moderation/escalate'

export type ReportReason = 'spam' | 'bullying' | 'nudity' | 'child_safety' | 'other'

export interface Report {
  id: string
  postId: string
  reporterId: string
  reason: ReportReason
  createdAt: string
}

/** Files a report about a post for the moderators to review. */
export function reportPost(postId: string, reporterId: string, reason: ReportReason, queues: ReviewQueues): Report {
  const report: Report = { id: randomUUID(), postId, reporterId, reason, createdAt: new Date().toISOString() }
  queues.standard.push(report)
  if (reason === 'child_safety') escalate(report, queues)
  return report
}

export function blockUser(blockerId: string, blockedId: string): void {
  const list = blocked.get(blockerId) ?? new Set<string>()
  list.add(blockedId)
  blocked.set(blockerId, list)
}

export function adProfile(user: User, interests: string[]): AdProfile {
  return {
    personalised: true,
    interests,
    ageBand: user.age < 18 ? 'teen' : 'adult',
  }
}
